1	/**
2	 * comment-command.ts — what counts as a command to Atomaton, in any text.
3	 *
4	 * A command is a line that asks for an agent (`/engineer`, `/engineer recover`, or the
5	 * `atomaton:dispatch` marker the machinery writes) or acts on a run (`/stop`,
6	 * `/resume`). This is the one definition of that syntax, and three readers share it:
7	 *
8	 *   - `parse_comment_command.ts` reads a person's comment to decide what to start
9	 *   - `domain/work/thread.ts`, through the thread reader, reads a thread to decide
10	 *     whose turn it is
11	 *   - `create_pr`, `create_sub_issue` and `create_root_issue` read an agent's body to refuse one
12	 *
13	 * They used to be two: the parser had its own patterns, and `extract_directive.ts` had
14	 * another idea of what a command line looks like. Three readers with two definitions is
15	 * how a body ends up refused by one and dispatched by another.
16	 *
17	 * ## Why an agent's body may not contain one
18	 *
19	 * A command is a request from someone entitled to make it. An agent writing
20	 * `/engineer` into a pull request body or an issue body is not asking; it is putting
21	 * words on a page that the next reader — `extract_directive.ts` on a pull request,
22	 * `resolve_entry_agent.ts` on an issue — will take for a request. The route an agent
23	 * has to start someone is a tool argument (`reviewer`, `launch_sub_agent`), which the
24	 * machinery writes in the form it reads and which the hand-off limit counts.
25	 *
26	 * Pure: text in, text out.
27	 */
28	import { AGENT_NAME_PATTERN } from "./agent-name.ts";
29	import { isControlCommand, type ControlCommand } from "./control-commands.ts";
30	
31	const COMMAND_RE = new RegExp(`^\\/(${AGENT_NAME_PATTERN})(?:\\s+(.*))?$`);
32	// Deliberately NOT `DISPATCH_TAG.read` from `adapters/github/tags.ts`, and the
33	// difference is load-bearing: this must be anchored to the start of a line so a
34	// dispatch marker quoted inside a human's comment cannot trigger a run, whereas
35	// `DISPATCH_TAG` matches anywhere in a body by design. The whitespace tolerance around
36	// `=` is likewise wider than the tag writer ever emits -- it costs nothing and this is
37	// the one place reading a marker a human may have retyped by hand.
38	const DISPATCH_RE = new RegExp(`^<!--\\s*atomaton:dispatch\\s*=\\s*(${AGENT_NAME_PATTERN})\\s*-->`);
39	
40	/**
41	 * How a run starts: continuing the saved session, or rebuilding it.
42	 *
43	 * Exported as a list, because the same two words are validated in three places — the
44	 * parser here, `restore_agent_session.ts`, and a bash `[[ ... ]]` in
45	 * `atomaton-runner.wac.ts` that is generated from this list rather than hand-kept in
46	 * step. A third mode added here reaches all three.
47	 */
48	export const SESSION_MODES = ["continue", "recover"] as const;
49	
50	export type SessionMode = (typeof SESSION_MODES)[number];
51	
52	/**
53	 * The two ways a person restarts work after a run that ended, as the notices say them.
54	 *
55	 * Every notice that hands a node back to a person after a run that left no usable
56	 * report — the failure notice (`report_run_failure.ts`), the run watch's notice
57	 * (`reconcile_run_ending.ts`) — says the same two things next, because the person
58	 * reading it has the same decision: carry the history, or archive it and start
59	 * clean. Which of those is right is a judgement about the work, and it belongs to
60	 * the person rather than to the machinery, so the notices name both and decide
61	 * nothing.
62	 *
63	 * Here rather than in either script, because the lines spell the two commands this
64	 * file is the one definition of — `/<agent>` and `/<agent> recover`, the two
65	 * `SESSION_MODES` — and a second copy of them beside the parser is a second
66	 * definition of the syntax waiting to disagree with it.
67	 */
68	export function recoveryLines(agent: string): string[] {
69	  return [
70	    `- Continue: comment \`/${agent}\` and put what to do next on the following lines.`,
71	    `- Start clean: comment \`/${agent} recover\`, which archives this session and rebuilds`,
72	    "  it from the issue.",
73	  ];
74	}
