export interface RunAtomaOpts {
  agentDefPath: string;
  toolsFilePath: string;
  promptFilePath: string;
  outSessionPath: string;
  templatePath?: string;
  skillsDir?: string;
  maxIterations?: number;
  env: Record<string, string>;
